glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D u_dissolveMap;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform Constant {
  vec4 flameColor1;
  vec4 flameColor2;
  vec2 spriteSize;
  float dissolveSlide;
  float dissolveDir;
  float dirStrength;
  float edgeWidth;
  float flameMixRange;
  float flameBlendMode;
};
vec2 getTileUV(vec2 uv) {
  float minSz  = min(spriteSize.x, spriteSize.y);
  vec2 tileSize = vec2(minSz / spriteSize.x, minSz / spriteSize.y);
  return mod(uv, tileSize) / tileSize;
}
vec2 dissolveMapUV(vec2 uv) {
  #if USE_TILE_UV
    return getTileUV(uv);
  #else
    return uv;
  #endif
}
float getDirectionalGradient(vec2 uv, float dir) {
    float d   = floor(dir + 0.5);
    float gx  = uv.x;
    float gy  = uv.y;
    float igx = 1.0 - gx;
    float igy = 1.0 - gy;
    if (d < 0.5) return gx;
    if (d < 1.5) return igx;
    if (d < 2.5) return igy;
    if (d < 3.5) return gy;
    if (d < 4.5) return (gx  + igy) * 0.5;
    if (d < 5.5) return (igx + igy) * 0.5;
    if (d < 6.5) return (gx  + gy ) * 0.5;
    return             (igx + gy ) * 0.5;
}
vec4 frag () {
  vec4 col = vec4(1, 1, 1, 1);
  col *= color;
  vec4 dissolveMap = texture(u_dissolveMap, dissolveMapUV(uv0));
  float dissolveNoise = dissolveMap.r;
  float dirGradient   = getDirectionalGradient(uv0, dissolveDir);
  float dissolveValue = mix(dissolveNoise, dirGradient, dirStrength);
  float ew = max(edgeWidth, 0.001);
  float fw = max(flameMixRange * ew, 0.001);
  float edgeEnd = dissolveSlide * (1.0 + ew);
  float alpha = clamp((dissolveValue - (edgeEnd - ew)) / ew, 0.0, 1.0);
  col.a *= alpha;
  col *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
  float flameOuterFade = clamp((edgeEnd - dissolveValue) / fw, 0.0, 1.0);
    if (flameOuterFade > 0.0 && dissolveSlide > 0.0) {
      vec4 color1 = flameColor1;
      vec4 color2 = vec4(flameColor2.rgb, col.a);
      float edgeDistance = (edgeEnd - fw * 0.375) - dissolveValue;
      float mixFactor = clamp(edgeDistance / fw + 0.01, 0.0, 1.0);
      vec4 flameCol = mix(color1, color2, mixFactor);
      float fade = pow(flameOuterFade, 0.3);
      float mode = floor(flameBlendMode + 0.5);
      vec4 blended;
      if (mode < 0.5) {
          blended = mix(col, flameCol, fade);
      } else if (mode < 1.5) {
          blended = mix(col, 1.0 - (1.0 - col) * (1.0 - flameCol), fade);
      } else {
          blended = col + flameCol * fade;
      }
      col = blended;
  }
  return col;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

